grant select on public.reference_institutions, public.reference_programmes, public.reference_institution_links, public.reference_programme_links, public.portal_catalog_visibility to anon, authenticated; create policy reference_institutions_catalog_read on public.reference_institutions for select to anon,authenticated using (exists(select 1 from public.reference_institution_links ril join public.portal_catalog_visibility pcv on pcv.university_id=ril.university_id where ril.reference_institution_id=reference_institutions.id and ril.status='verified' and pcv.status='published')); create policy reference_programmes_catalog_read on public.reference_programmes for select to anon,authenticated using (exists(select 1 from public.reference_institution_links ril join public.portal_catalog_visibility pcv on pcv.university_id=ril.university_id where ril.reference_institution_id=reference_programmes.reference_institution_id and ril.status='verified' and pcv.status='published')); create policy reference_institution_links_catalog_read on public.reference_institution_links for select to anon,authenticated using (status='verified' and exists(select 1 from public.portal_catalog_visibility pcv where pcv.university_id=reference_institution_links.university_id and pcv.status='published')); create policy reference_programme_links_catalog_read on public.reference_programme_links for select to anon,authenticated using (status='verified'); create policy portal_catalog_visibility_public_read on public.portal_catalog_visibility for select to anon,authenticated using (status='published');
